// ── 40. Three-Year Squad Planning ─────────────────────────────────────────────
const s40: SlotSpec = {
  n: 40,
  storyType: "explainer",
  build(a) {
    const sql = `SELECT ${YEAR()} year, pl.name, SUM(CASE WHEN i.batting_team_id IN ${a.T} THEN d.batter_runs ELSE 0 END) runs, SUM(CASE WHEN i.bowling_team_id IN ${a.T} AND ${LEGAL} THEN 1 ELSE 0 END) bowled
      FROM deliveries d JOIN innings i ON i.innings_id = d.innings_id JOIN matches m ON m.match_id = d.match_id JOIN players pl ON pl.player_id = CASE WHEN i.batting_team_id IN ${a.T} THEN d.batter_id ELSE d.bowler_id END
      WHERE ${REGULATION} AND (i.batting_team_id IN ${a.T} OR i.bowling_team_id IN ${a.T}) GROUP BY year, pl.name`;
    const rs = a.rows<{ year: number; name: string; runs: number; bowled: number }>(sql);
    const years = [...new Set(rs.map((r) => r.year))].sort();
    const rows: Row[] = [];
    for (const y of years) {
      if (!years.includes(y - 1)) continue;
      const prev = new Set(rs.filter((r) => r.year === y - 1).map((r) => r.name));
      const cur = rs.filter((r) => r.year === y);
      const tot = cur.reduce((x, r) => x + r.runs + r.bowled, 0);
      const kept = cur.filter((r) => prev.has(r.name)).reduce((x, r) => x + r.runs + r.bowled, 0);
      rows.push({ season: String(y), continuity: dp((kept / Math.max(1, tot)) * 100), year: y });
    }
    a.table("cont-series", `${a.code} squad continuity by season`, "Share of runs scored plus balls bowled by players who also played the previous season", rows.length, "seasons", sql, rows.map(({ season, continuity }) => ({ season, continuity })));
    const avg = rows.reduce((x, r) => x + (r.continuity as number), 0) / Math.max(1, rows.length);
    const last = rows[rows.length - 1];
    const tok = {
      avg: a.pct("cont-avg", avg, `${a.poss} average season-to-season continuity`, { filters: "Share of runs plus balls from returning players", n: rows.length, nUnit: "seasons", sql, check: floor(rows.length, 2, "seasons") }, 0),
      last: a.pct("cont-last", last.continuity as number, `${a.code} continuity in ${last.season}`, { filters: String(last.season), n: 1, nUnit: "season", sql, check: derived("taken from the season table") }, 0),
    };
    const sorted = [...rows].sort((x, y) => (y.continuity as number) - (x.continuity as number));
    const hi = sorted[0], lo = sorted[sorted.length - 1];
    const tokHi = a.text("cont-hi", String(hi.season), `${a.poss} most continuous season`, { filters: "Season table", n: rows.length, nUnit: "seasons", sql, check: derived("max") });
    const MEGA = [2011, 2014, 2018, 2022, 2025];
    const mg = rows.filter((r) => MEGA.includes(r.year as number)), ot = rows.filter((r) => !MEGA.includes(r.year as number));
    const mean = (xs: Row[]) => xs.reduce((x, r) => x + (r.continuity as number), 0) / Math.max(1, xs.length);
    const tokMega = mg.length ? a.pct("cont-mega", mean(mg), `${a.poss} average continuity in mega-auction seasons`, { filters: "Seasons after a mega-auction: 2011, 2014, 2018, 2022, 2025", n: mg.length, nUnit: "seasons", sql, check: derived("mean of season table") }, 0) : "";
    const tokOther = ot.length ? a.pct("cont-other", mean(ot), `${a.poss} average continuity in other seasons`, { filters: "All other seasons", n: ot.length, nUnit: "seasons", sql, check: derived("mean of season table") }, 0) : "";
    const megaLine = mg.length && ot.length ? `In seasons that followed a mega-auction, returning players did ${tokMega} of the work on average, against ${tokOther} in other seasons.` : `There are too few seasons on each side of a mega-auction to compare.`;
    const tokLo = a.text("cont-lo", String(lo.season), `${a.poss} least continuous season`, { filters: "Season table", n: rows.length, nUnit: "seasons", sql, check: derived("min") });
    return {
      dek: `Can ${a.name} build beyond one season? Squad continuity, the share of each season's work done by returning players, shows how much they plan in cycles.`,
      excerpt: `On average, ${a.poss} returning players have done a measurable share of each season's batting and bowling. Mega-auctions reset that number; good planning keeps a core through them.`,
      keyTakeaways: [
        `On average ${tok.avg} of ${a.poss} runs and balls bowled came from players who had also played for them the previous season.`,
        `In ${last.season} the figure was ${tok.last}.`,
        `Their most continuous season was ${tokHi}; their least, ${tokLo}.`,
      ],
      sections: [
        { heading: "Seasons or Cycles", body: [
          `IPL squads are rebuilt at mega-auctions every few years and adjusted at mini-auctions in between. A franchise that plans in three-year cycles keeps a core through the reset; one that plans season by season rebuilds from scratch.`,
          `On average ${tok.avg} of ${a.poss} runs scored and balls bowled have come from players who also played for them the season before.`,
        ], chartIds: ["cont-chart"] },
        { heading: "Where the Resets Came", body: [
          `Their most continuous season was ${tokHi} and their least continuous ${tokLo}. In ${last.season}, returning players did ${tok.last} of the work.`,
          megaLine,
        ] },
        { heading: "Planning Through the Reset", body: [
          `A three-year plan names the core roles to keep, the ones to buy and the young players to develop into the next core. Retention choices then follow from the plan rather than from the last season's form.`,
          `For ${a.code}, that means deciding at each mini-auction which players are meant to be in the next mega-auction's retention list.`,
        ] },
        { heading: "Continuity Is Not Always Good", body: [
          `Keeping a core is only valuable if the core is good. A franchise can be highly continuous and consistently mediocre.`,
          `{{hyp:continuity}}`,
        ] },
        { heading: "CricField Verdict: Plan the Core Three Years Out", body: [
          `${a.name} should plan their core across auction cycles and treat each mini-auction as a step towards the next mega-auction.`,
          `Continuity should be a result of that plan, not a goal in itself.`,
        ] },
      ],
      charts: [{ id: "cont-chart", type: "column", title: "Squad continuity by season", subtitle: `${a.code}: share of runs and balls from returning players`, table: "cont-series", xKey: "season", series: [{ key: "continuity", label: "Continuity" }], xLabel: "Season", unit: "% of runs plus balls", takeaway: mg.length && ot.length && mean(mg) < mean(ot) ? "Continuity is lower in seasons that follow a mega-auction." : "Continuity varies from season to season.", ariaLabel: `Column chart of ${a.code} squad continuity by season.` }],
      hypotheses: [hyp("continuity", "higher season-to-season continuity is associated with better results across franchises.", "The relationship between continuity and results has not been tested.", "Correlate continuity with win rate across all franchise-seasons.")],
      players: [],
      seasons: [`${a.c.firstYear}–2026`],
      hero: { narrative: `${a.name}'s core group.`, wanted: `${a.name} players celebrating together.`, query: `${a.name} players celebrate` },
      related: [33, 91, 67],
      seo: { metaTitle: metaTitle(`Three-year squad planning at ${a.code}`), metaDescription: metaDesc(`How much of each ${a.name} season's work was done by returning players, and how to plan a core across auction cycles.`) },
      methodology: "Continuity = runs scored plus legal balls bowled by players who also batted or bowled for the franchise in the previous season, as a share of the season's total. Regulation innings. Generated by scripts/editorial/engine.",
    };
  },
};

